    'guards/JwtAuthGuard.html': {
      url: 'guards/JwtAuthGuard.html',
      title: 'guard - JwtAuthGuard',
      body: "\n                   \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n    Guards\n    JwtAuthGuard\n\n\n\n    \n    src/modules/auth/guards/jwt-auth.guard.ts\n\n\n\n        \n            Info\n        \n        \n            API\n        \n        \n            Source\n        \n\n\n\n        \n\n\n\n\n\n                    \n            Relationships\n\n            \n                \n                    Used by\n                        \n                                \n                                            AuthModule\n                                \n                        \n                \n\n                \n                    Depends on\n                        No results matching.\n                \n            \n        \n        \n\n        \n                \n    Index\n\n        \n            \n                \n                    \n                        Methods\n                    \n                    \n                        \n                            \n                                M\n                                    Async\n                                canActivate\n                            \n                        \n                    \n                \n            \n        \n\n\n\n\n\n\n\n                \n    Constructor\n        \n            \n                \n                    \nconstructor(jwtService: JwtService)\n                    \n                \n                        \n                            \n                                Defined in src/modules/auth/guards/jwt-auth.guard.ts:6\n                            \n                        \n\n                \n                    \n                            \n                                    Parameters :\n                                    \n                                        \n                                            \n                                                Name\n                                                    Type\n                                                Optional\n                                            \n                                        \n                                        \n                                                \n                                                        jwtService\n                                                  \n                                                        \n                                                                    JwtService\n                                                        \n                                                  \n                                                    \n                                                            No\n                                                    \n                                                    \n                                                \n                                        \n                                    \n                            \n                    \n                \n            \n        \n\n\n                \n    \n    \n        Methods\n    \n    \n        \n            \n                \n                    \n                    \n                            Async\n                        canActivate\n                        \n                    \n                \n            \n            \n                \n                        \n                    canActivate(context: ExecutionContext)\n                \n            \n\n\n                    \n                        \n                            Defined in src/modules/auth/guards/jwt-auth.guard.ts:9\n                        \n                    \n\n\n            \n                \n\n                            \n                                Parameters :\n                                \n                                \n                                    \n                                        \n                                            Name\n                                                Type\n                                            Optional\n                                        \n                                    \n                                    \n                                        \n                                                context\n                                            \n                                                        ExecutionContext\n                                            \n\n                                            \n                                                    No\n                                            \n\n\n                                        \n                                    \n                                \n                            \n                        \n                            Returns :     Promise\n\n                        \n                            \n                                \n                            \n                \n            \n        \n    \n\n\n        \n\n\n        \n            import { Injectable, CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';\nimport { JwtService } from '@nestjs/jwt';\n\n@Injectable()\nexport class JwtAuthGuard implements CanActivate {\n  constructor(private readonly jwtService: JwtService) {}\n\n  async canActivate(context: ExecutionContext): Promise {\n    const request = context.switchToHttp().getRequest();\n    const authHeader = request.headers.authorization;\n\n    if (!authHeader) {\n      throw new UnauthorizedException('No se proporcionó el token de autenticación.');\n    }\n\n    const [type, token] = authHeader.split(' ');\n\n    if (type !== 'Bearer' || !token) {\n      throw new UnauthorizedException('Formato de token inválido (debe ser Bearer ).');\n    }\n\n    try {\n      // Verificamos el token con la clave secreta\n      const payload = await this.jwtService.verifyAsync(token);\n      \n      // Inyectamos el payload decodificado en el request (aquí viaja id, rol, estado, etc.)\n      request.user = payload;\n    } catch (error) {\n      throw new UnauthorizedException('Token inválido o expirado.');\n    }\n\n    return true;\n  }\n}\n        \n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
    },
