      body: "\n                   \n\n\n\n\n\n\n\n\n\n\n  Controllers\n  UsuariosController\n\n\n\n    \n    src/modules/gestion/controllers/usuarios.controller.ts\n\n\n\n        \n            Info\n        \n        \n            API\n        \n        \n            Source\n        \n\n\n\n    \n            \n                Prefix\n            \n            \n                usuarios\n            \n\n\n\n\n\n\n                \n            Relationships\n\n            \n                \n                    Used by\n                        \n                                \n                                            GestionModule\n                                \n                        \n                \n\n                \n                    Depends on\n                        No results matching.\n                \n            \n        \n    \n\n    \n            \n    Index\n\n        \n            \n                \n                    \n                        Methods\n                    \n                    \n                        \n                            \n                                M\n                                    \n                                    \n                                    \n                                    \n                                    Async\n                                listarPacientes\n                            \n                            \n                                M\n                                    \n                                    \n                                    \n                                    Async\n                                obtenerPerfil\n                            \n                        \n                    \n                \n            \n        \n\n\n\n\n\n\n\n            \n    \n    \n        Methods\n    \n    \n        \n            \n                \n                    \n                    \n                            \n                            \n                            \n                            \n                            Async\n                        listarPacientes\n                        \n                    \n                \n            \n            \n                \n                        \n                    listarPacientes()\n                \n            \n\n            \n                \n                    Decorators : \n                    \n                    @Get('pacientes')@Roles(RolesUsuarios.ADMINISTRADOR)@ApiOperation({summary: 'Listar los pacientes activos (para reservar a su nombre)'})@ApiOkResponse({type: undefined})\n                \n            \n\n                    \n                        \n                            Defined in src/modules/gestion/controllers/usuarios.controller.ts:31\n                        \n                    \n\n\n            \n                \n\n                        \n                            Returns :     unknown\n\n                        \n                \n            \n        \n    \n    \n        \n            \n                \n                    \n                    \n                            \n                            \n                            \n                            Async\n                        obtenerPerfil\n                        \n                    \n                \n            \n            \n                \n                        \n                    obtenerPerfil(req: { user: UsuarioAutenticado })\n                \n            \n\n            \n                \n                    Decorators : \n                    \n                    @Get('perfil')@ApiOperation({summary: 'Ver los datos del usuario autenticado'})@ApiOkResponse({type: UsuarioResponseDto})\n                \n            \n\n                    \n                        \n                            Defined in src/modules/gestion/controllers/usuarios.controller.ts:23\n                        \n                    \n\n\n            \n                \n\n                            \n                                Parameters :\n                                \n                                \n                                    \n                                        \n                                            Name\n                                                Type\n                                            Optional\n                                        \n                                    \n                                    \n                                        \n                                                req\n                                            \n                                                            { user: UsuarioAutenticado }\n                                            \n\n                                            \n                                                    No\n                                            \n\n\n                                        \n                                    \n                                \n                            \n                        \n                            Returns :     unknown\n\n                        \n                            \n                                \n                            \n                \n            \n        \n    \n\n    \n\n\n    \n        // src/modules/gestion/controllers/usuarios.controller.ts\nimport { Controller, Get, UseGuards, Req } from '@nestjs/common';\nimport { ApiTags, ApiBearerAuth, ApiOperation, ApiOkResponse } from '@nestjs/swagger';\nimport { UsuariosService } from '../services/usuarios.service';\nimport { UsuarioAutenticado } from '../services/reservas.service';\nimport { UsuarioResponseDto } from '../dtos/output/usuario-response.dto';\nimport { RolesUsuarios } from '../enums/roles-usuarios.enum';\nimport { JwtAuthGuard } from '../../auth/guards/jwt-auth.guard';\nimport { RolesGuard } from '../../auth/guards/roles.guard';\nimport { Roles } from '../../auth/decorators/roles.decorator';\n\n@ApiTags('Usuarios')\n@ApiBearerAuth()\n@UseGuards(JwtAuthGuard, RolesGuard)\n@Controller('usuarios')\nexport class UsuariosController {\n  constructor(private readonly usuariosService: UsuariosService) {}\n\n  // Sin @Roles: cualquier usuario autenticado puede ver su propio perfil\n  @Get('perfil')\n  @ApiOperation({ summary: 'Ver los datos del usuario autenticado' })\n  @ApiOkResponse({ type: UsuarioResponseDto })\n  async obtenerPerfil(@Req() req: { user: UsuarioAutenticado }) {\n    return this.usuariosService.buscarPorId(req.user.id);\n  }\n\n  @Get('pacientes')\n  @Roles(RolesUsuarios.ADMINISTRADOR)\n  @ApiOperation({ summary: 'Listar los pacientes activos (para reservar a su nombre)' })\n  @ApiOkResponse({ type: [UsuarioResponseDto] })\n  async listarPacientes() {\n    return this.usuariosService.listarPacientes();\n  }\n}\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
