      body: "\n                   \n\n\n\n\n\n\n\n\n\n\n\n\n\n  Injectables\n  UsuariosService\n\n\n\n    \n    src/modules/gestion/services/usuarios.service.ts\n\n\n\n        \n            Info\n        \n        \n            API\n        \n        \n            Source\n        \n\n\n\n    \n\n\n\n\n\n                \n            Relationships\n\n            \n                \n                    Used by\n                        \n                                \n                                            GestionModule\n                                \n                        \n                \n\n                \n                    Depends on\n                        No results matching.\n                \n            \n        \n    \n\n    \n            \n    Index\n\n        \n            \n                \n                    \n                        Methods\n                    \n                    \n                        \n                            \n                                M\n                                    Async\n                                buscarPorId\n                            \n                            \n                                M\n                                    Async\n                                listarPacientes\n                            \n                        \n                    \n                \n            \n        \n\n\n\n\n\n\n\n            \n    Constructor\n        \n            \n                \n                    \nconstructor(usuarioRepo: Repository)\n                    \n                \n                        \n                            \n                                Defined in src/modules/gestion/services/usuarios.service.ts:12\n                            \n                        \n\n                \n                    \n                            \n                                    Parameters :\n                                    \n                                        \n                                            \n                                                Name\n                                                    Type\n                                                Optional\n                                            \n                                        \n                                        \n                                                \n                                                        usuarioRepo\n                                                  \n                                                        \n                                                                        Repository\n                                                        \n                                                  \n                                                    \n                                                            No\n                                                    \n                                                    \n                                                \n                                        \n                                    \n                            \n                    \n                \n            \n        \n\n\n            \n    \n    \n        Methods\n    \n    \n        \n            \n                \n                    \n                    \n                            Async\n                        buscarPorId\n                        \n                    \n                \n            \n            \n                \n                        \n                    buscarPorId(id: number)\n                \n            \n\n\n                    \n                        \n                            Defined in src/modules/gestion/services/usuarios.service.ts:18\n                        \n                    \n\n\n            \n                \n\n                            \n                                Parameters :\n                                \n                                \n                                    \n                                        \n                                            Name\n                                                Type\n                                            Optional\n                                        \n                                    \n                                    \n                                        \n                                                id\n                                            \n                                                            number\n                                            \n\n                                            \n                                                    No\n                                            \n\n\n                                        \n                                    \n                                \n                            \n                        \n                            Returns :         Promise\n\n                        \n                            \n                                \n                            \n                \n            \n        \n    \n    \n        \n            \n                \n                    \n                    \n                            Async\n                        listarPacientes\n                        \n                    \n                \n            \n            \n                \n                        \n                    listarPacientes()\n                \n            \n\n\n                    \n                        \n                            Defined in src/modules/gestion/services/usuarios.service.ts:27\n                        \n                    \n\n\n            \n                \n\n                        \n                            Returns :         Promise\n\n                        \n                \n            \n        \n    \n\n\n\n    \n\n\n    \n        import { Injectable, NotFoundException } from '@nestjs/common';\nimport { InjectRepository } from '@nestjs/typeorm';\nimport { Repository } from 'typeorm';\nimport { Usuario } from '../entities/usuario.entity';\nimport { UsuarioResponseDto } from '../dtos/output/usuario-response.dto';\nimport { EstadosUsuarios } from '../enums/estados-usuarios.enum';\nimport { RolesUsuarios } from '../enums/roles-usuarios.enum';\nimport { aUsuarioDto } from '../mappers/mappers';\n\n@Injectable()\nexport class UsuariosService {\n  constructor(\n    @InjectRepository(Usuario)\n    private readonly usuarioRepo: Repository,\n  ) {}\n\n  async buscarPorId(id: number): Promise {\n    const usuario = await this.usuarioRepo.findOne({ where: { id } });\n    if (!usuario) {\n      throw new NotFoundException('Usuario no encontrado.');\n    }\n    return aUsuarioDto(usuario);\n  }\n\n  // Pacientes activos, para que el administrador elija a quién reservarle el turno\n  async listarPacientes(): Promise {\n    const pacientes = await this.usuarioRepo.find({\n      where: { rol: RolesUsuarios.PACIENTE, estado: EstadosUsuarios.ACTIVO },\n      order: { apellidos: 'ASC', nombres: 'ASC' },\n    });\n    return pacientes.map(aUsuarioDto);\n  }\n}\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
